        "sampleValue": "限额2小时"
      },
      "riskStatusText": {
        "type": "string",
        "description": "超过阈值后的风险状态展示文本",
        "sampleValue": "风险状态"
      },
      "riskColor": {
        "type": "string",
        "description": "风险状态文本和强调标记使用的颜色",
        "sampleValue": "#ffed6f21"
      },
      "app0Name": {
        "type": "string",
        "description": "常用应用列表第一项名称",
        "sampleValue": "微信"
      },
      "app1Name": {
        "type": "string",
        "description": "常用应用列表第二项名称",
        "sampleValue": "游戏"
      },
      "app2Name": {
        "type": "string",
        "description": "常用应用列表第三项名称",
        "sampleValue": "视频"
      }
    },
    "tasks": {
      "task0Label": {
        "type": "string",
        "description": "右侧动作区第一项可勾选任务名称",
        "sampleValue": "休息提醒"
      },
      "task0Selected": {
        "type": "boolean",
        "description": "第一项任务的勾选状态",
        "sampleValue": true
      },
      "task1Label": {
        "type": "string",
        "description": "右侧动作区第二项可勾选任务名称",
        "sampleValue": "限制游戏"
      },
      "task1Selected": {
        "type": "boolean",
        "description": "第二项任务的勾选状态",
        "sampleValue": false
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/icon_timing.png",
      "description": "防沉迷场景的计时图标，适合表达应用使用时长监控和时间风险提醒。"
    }
  ]
}

